-- Add every distinct surf location from the operator-supplied LazySurfer gap list.
-- Ten supplied labels resolve to existing rows, a duplicate coordinate, an overlapping corridor,
-- or a non-spot hazard label; those decisions are preserved in the companion research artifact.

BEGIN;

CREATE TEMP TABLE _east_coast_beaches (
  id uuid PRIMARY KEY, name text NOT NULL, slug text NOT NULL, city text NOT NULL,
  state text NOT NULL, region text NOT NULL, timezone text NOT NULL,
  lat double precision NOT NULL, lon double precision NOT NULL,
  break_type text NOT NULL, skill_level text NOT NULL, hazards text[] NOT NULL,
  features text[] NOT NULL, description text NOT NULL, parking_tips text NOT NULL,
  access_tips text NOT NULL, wave_tips text NOT NULL, crowd_tips text NOT NULL,
  best_conditions_prose text NOT NULL, warnings text[] NOT NULL, crowd_level text NOT NULL,
  swell_min integer NOT NULL, swell_max integer NOT NULL, swell_center integer NOT NULL,
  swell_halfwidth integer NOT NULL, aspect integer NOT NULL, offshore integer NOT NULL,
  tide_stage text, tide_station_id text NOT NULL, tide_note text NOT NULL,
  nws_office text NOT NULL, nws_zone text NOT NULL, nws_grid text NOT NULL,
  nws_original_lat double precision NOT NULL, nws_original_lon double precision NOT NULL,
  nws_used_lat double precision NOT NULL, nws_used_lon double precision NOT NULL,
  nws_shift_km double precision NOT NULL, nws_bearing integer NOT NULL,
  persona public.beach_persona NOT NULL, decay real NOT NULL, best_months integer[] NOT NULL,
  recommendation_eligible boolean NOT NULL, seo_indexable boolean NOT NULL,
  is_private boolean NOT NULL, eligibility_reason text NOT NULL,
  editorial_sources jsonb NOT NULL, supplied_name text NOT NULL, source_url text NOT NULL,
  precision_review jsonb NOT NULL, preferred_tide_direction text
) ON COMMIT DROP;

INSERT INTO _east_coast_beaches VALUES
