DO $$
BEGIN
  IF (SELECT count(*) FROM _east_coast_beaches) <> 61 THEN
    RAISE EXCEPTION 'Expected 61 canonical new beaches';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.beaches b JOIN _east_coast_beaches i
      ON b.id <> i.id
     AND (lower(b.slug) = lower(i.slug) OR lower(b.name) = lower(i.name))
  ) THEN
    RAISE EXCEPTION 'East Coast import conflicts with an existing active beach';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.beaches b JOIN _east_coast_beaches i USING (id)
    WHERE b.deleted_at IS NOT NULL OR b.slug IS DISTINCT FROM i.slug
       OR b.name IS DISTINCT FROM i.name OR b.lat IS DISTINCT FROM i.lat
       OR b.lon IS DISTINCT FROM i.lon
  ) THEN RAISE EXCEPTION 'Existing import UUID differs from reviewed identity or coordinate'; END IF;
END $$;

INSERT INTO public.beaches (
  id, name, slug, city, state, country, region, timezone, lat, lon,
  break_type, skill_level, hazards, features, description, parking_tips,
  access_tips, wave_tips, crowd_tips, best_conditions_prose, warnings,
  crowd_level, swell_window_min_deg, swell_window_max_deg,
  swell_window_center_deg, swell_window_halfwidth_deg, aspect_deg,
  wind_offshore_deg, wind_offshore_tol_deg, wind_cross_shore_ok_kt,
  wind_onshore_bad_kt, preferred_tide_ft_min, preferred_tide_ft_max,
  preferred_tide_direction, tide_direction_sensitivity, preference_model,
  best_months, nws_office, nws_forecast_zone, cdip_eligible, persona,
  deepwater_decay_factor, editorial_sources, editorial_reviewed_at,
  seo_indexable, recommendation_eligible, is_private,
  swell_window_min_deg_v2, swell_window_max_deg_v2,
  swell_window_center_deg_v2, swell_window_halfwidth_deg_v2,
  swell_window_v2_method, swell_window_v2_analyzed_at
)
SELECT
  id, name, slug, city, state, 'USA', region, timezone, lat, lon,
  break_type, skill_level, hazards, features, description, parking_tips,
  access_tips, wave_tips, crowd_tips, best_conditions_prose, warnings,
  crowd_level, swell_min, swell_max, swell_center, swell_halfwidth, aspect,
  offshore, 45, 12, 8, NULL, NULL,
  preferred_tide_direction,
  'low',
  jsonb_build_object(
    'tide', tide_stage,
    'precision_review', precision_review,
    'recommendation_ready', recommendation_eligible,
    'eligibility_reason', eligibility_reason,
    'tide_calibration', jsonb_build_object(
      'station_id', tide_station_id, 'datum', 'MLLW', 'status', precision_review->>'tide_status',
      'station_role', 'editorial_reference_not_runtime_override',
      'preferred_direction', preferred_tide_direction,
      'direction_sensitivity', 'low', 'hard_gate', false, 'note', tide_note
    ),
    'skill_validation', jsonb_build_object(
      'minimum_skill', skill_level, 'status', precision_review->'skill_review'->>'status',
      'conditions_dependent', true, 'hard_safety_gate', break_type IN ('inlet', 'jetty')
    ),
    'forecast_anchors', jsonb_build_object(
      'marine_provider', 'open_meteo', 'nws_grid', nws_grid, 'nws_point_reviewed', true,
      'nws_original_coordinate', jsonb_build_array(nws_original_lat, nws_original_lon),
      'nws_used_coordinate', jsonb_build_array(nws_used_lat, nws_used_lon),
      'nws_offshore_shift_km', nws_shift_km, 'nws_offshore_bearing_deg', nws_bearing
    ),
    'catalog_source', jsonb_build_object('supplied_name', supplied_name, 'url', source_url)
  ),
  best_months, nws_office, nws_zone, false, persona, decay,
  editorial_sources, '2026-09-27T00:00:00Z'::timestamptz,
  seo_indexable, recommendation_eligible, is_private,
  swell_min, swell_max, swell_center, swell_halfwidth,
  'reviewed_local_exposure_v1', '2026-09-27T00:00:00Z'::timestamptz
FROM _east_coast_beaches
ON CONFLICT (id) DO NOTHING;

UPDATE public.beaches
SET
  break_type = 'beach',
  hazards = ARRAY['rip currents','shifting sandbars','rapidly changing currents']::text[],
  description = 'Frisco Pier Beach is the historical surf-place name for the exposed Atlantic beach break at Frisco Beach Access; the former pier and pier house were removed. The representative coordinate marks nearshore water, not a fixed takeoff.',
  access_tips = 'Use the current National Park Service Frisco Beach Access and obey Cape Hatteras closures, ORV rules, and posted ocean-safety guidance.',
  crowd_tips = 'Spread out across shifting peaks and keep clear of swimmers and marked access corridors.',
  editorial_sources = jsonb_set(
    editorial_sources,
    '{0}',
    '{"url":"https://www.nps.gov/caha/planyourvisit/physical-mobility.htm","publisher":"National Park Service","retrievedAt":"2026-09-26","fields":["identity","public_access","current_access"]}'::jsonb
  ) || jsonb_build_array(jsonb_build_object(
    'url', 'https://www.nps.gov/caha/learn/news/17_058.htm',
    'publisher', 'National Park Service',
    'retrievedAt', '2026-09-26',
    'fields', jsonb_build_array('former_pier_removal', 'historical_context')
  ))
WHERE slug = 'frisco-pier-beach-frisco-nc'
  AND description LIKE '%pier-influenced surf zone%';

UPDATE public.beaches
SET
  access_tips = 'From May 1 through September 30, surfing is prohibited from the Inlet through 27th Street from 10:00 a.m. to 5:30 p.m. except within the designated rotating surf beach; confirm the posted daily location before surfing 8th Street.',
  warnings = warnings || ARRAY['May 1–September 30 restriction: 10:00 a.m.–5:30 p.m.; use only the designated rotating surf beach during those hours']::text[]
WHERE slug = '8th-street-ocean-city-md'
  AND access_tips = 'Use the official public access serving this shoreline and obey closures, dune protections, and seasonal surf-zone rules.';

