UPDATE public.beaches AS b
SET
  swell_access_factors = terrain.swell_factors,
  wind_exposure_factors = terrain.wind_factors,
  terrain_method = 'dem_horizon_v1',
  terrain_params = '{"max_radius_m":5000,"blockage_threshold_m":3000,"swell_ray_length_m":3500,"step_m":60,"angle_mid":8,"k":3,"min_exposure":0.15,"wrap_lambda":0.04,"max_wrap_angle":45,"smoothing_kernel":[0.25,0.5,0.25],"dem_source":"aws_terrain_tiles","resolution_m":30,"near_far_split_m":500}'::jsonb,
  terrain_params_hash = 'ca84656a8a0e721a7c47813f541c147bcbe81157b1d6ed054c715b21119cc659',
  terrain_analyzed_at = '2026-09-27T00:00:00Z'::timestamptz,
  wind_analyzed_at = '2026-09-27T00:00:00Z'::timestamptz,
  swell_analyzed_at = '2026-09-27T00:00:00Z'::timestamptz,
  terrain_status = 'ok',
  terrain_enabled = true,
  terrain_analysis_debug = jsonb_build_object(
    'model_version', 'custom_spot_terrain_v1',
    'bathymetric_amplification_claim', false,
    'note', 'Coordinate-derived DEM and landmask fingerprint; no scalar shoaling gain or loss is claimed.'
  )
FROM terrain_factors AS terrain
WHERE b.id = terrain.beach_id
  AND (
    b.terrain_params_hash IS NULL
    OR b.terrain_params_hash = 'ca84656a8a0e721a7c47813f541c147bcbe81157b1d6ed054c715b21119cc659'
  );

INSERT INTO public.beach_sources (beach_id, forecast_source_id)
SELECT id, 'open_meteo'
FROM _east_coast_beaches
ON CONFLICT (beach_id) DO NOTHING;

-- Surfline permission confirmed by operator 2026-09-27; direct HLS follows Virginia.
-- Exact aliases and HTTP/FOV evidence: research JSON camera_review.
CREATE TEMP TABLE _east_coast_cameras (
  beach_id uuid PRIMARY KEY,
  camera_url text NOT NULL,
  thumbnail_url text NOT NULL
) ON COMMIT DROP;

INSERT INTO _east_coast_cameras
SELECT beach_id,
  'https://hls.cdn-surfline.com/ohio/' || alias || '/playlist.m3u8',
  'https://camstills.cdn-surfline.com/us-east-2/' || alias || '/latest_small.jpg'
FROM (VALUES
  ('240dcdda-c950-5308-b143-d3b88c7431ce'::uuid, 'ec-longsands'),
  ('f9088599-fca8-528e-a34e-01df2a5fca11'::uuid, 'ec-jennettesnorth'),
  ('6a59945d-d046-5265-87a9-3a51c847d568'::uuid, 'ec-kittyhawk'),
  ('4626d7a9-4a0c-5f19-9f07-13fc4593b981'::uuid, 'ec-oceananapier'),
  ('0e2b136a-9b2c-5b1c-a063-991ee8c568bd'::uuid, 'ec-bogueinletpier'),
  ('758ca27d-73c6-57d9-a4cf-fd20c532273e'::uuid, 'ec-cherrypiersouth'),
  ('b702951a-21d4-505f-b02c-8f376db7f639'::uuid, 'ec-cherrypiernorth')
) AS cameras(beach_id, alias);

DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM public.beach_sources s JOIN _east_coast_cameras c USING (beach_id)
    WHERE (s.camera_url IS NOT NULL AND s.camera_url IS DISTINCT FROM c.camera_url)
       OR (s.thumbnail_url IS NOT NULL AND s.thumbnail_url IS DISTINCT FROM c.thumbnail_url)
  ) THEN RAISE EXCEPTION 'Existing camera or thumbnail differs from reviewed Surfline mapping'; END IF;
END $$;

UPDATE public.beach_sources s
SET camera_url = c.camera_url, thumbnail_url = c.thumbnail_url
FROM _east_coast_cameras c
WHERE s.beach_id = c.beach_id
  AND (s.camera_url IS DISTINCT FROM c.camera_url OR s.thumbnail_url IS DISTINCT FROM c.thumbnail_url);

WITH hero_photos (
  beach_id, source_id, image_url, thumb_url, title, creator_name,
  creator_url, license_code, license_url, attribution_html
) AS (
