INSERT INTO public.beach_photos (
  beach_id, source, source_id, image_url, thumb_url, title, creator_name,
  creator_url, license_code, license_url, attribution_html, approved, fetched_at
)
SELECT
  beach_id, 'wikimedia', source_id, image_url, thumb_url, title, creator_name,
  creator_url, license_code, license_url, attribution_html, true,
  '2026-09-26T00:00:00Z'::timestamptz
FROM hero_photos
ON CONFLICT (beach_id, source, source_id) DO NOTHING;

WITH fallback_photos AS (
  SELECT
    b.id AS beach_id,
    CASE
      WHEN b.state = 'FL' AND (b.region LIKE '%Gulf%' OR b.region LIKE '%Panhandle%') THEN 'florida-gulf-v1'
      WHEN b.state = 'FL' THEN 'florida-atlantic-v1'
      WHEN b.state = 'NC' THEN 'north-carolina-coast-v1'
      WHEN b.state = 'SC' THEN 'south-carolina-v1'
      WHEN b.state = 'VA' THEN 'virginia-beach-v1'
      WHEN b.state = 'MA' THEN 'massachusetts-north-shore-v1'
    END AS source_id
  FROM _east_coast_beaches AS b
  WHERE b.state IN ('FL', 'NC', 'SC', 'VA', 'MA')
    AND NOT EXISTS (
      SELECT 1 FROM public.beach_photos AS p
      WHERE p.beach_id = b.id AND p.approved AND p.deleted_at IS NULL
    )
)
INSERT INTO public.beach_photos (
  beach_id, source, source_id, image_url, thumb_url, title,
  license_code, attribution_html, approved, fetched_at
)
SELECT
  beach_id,
  'ai_generated',
  source_id,
  '/images/beaches/east-coast/' || source_id || '.webp',
  '/images/beaches/east-coast/' || source_id || '.webp',
  'Regional surf coastline — illustrative fallback',
  'openai-generated',
  'AI-generated representative regional coastline. Illustrative only; not this exact break or current conditions.',
  true,
  '2026-09-26T00:00:00Z'::timestamptz
FROM fallback_photos
ON CONFLICT (beach_id, source, source_id) DO NOTHING;

CREATE TEMP TABLE _east_coast_aliases (
  target_id uuid PRIMARY KEY, target_slug text NOT NULL, supplied_name text NOT NULL, source_url text NOT NULL
) ON COMMIT DROP;

