  ('6ee5c419-ebaa-416f-8026-85b144767eba', 'camp-pendleton-virginia-beach-va', 'Croatan to Pendleton', 'https://lazysurfer.app/spots/croatan-to-pendleton.html');

UPDATE public.beaches AS b
SET preference_model = jsonb_set(
  COALESCE(b.preference_model, '{}'::jsonb),
  '{catalog_aliases}',
  COALESCE(b.preference_model->'catalog_aliases', '[]'::jsonb) ||
    jsonb_build_array(jsonb_build_object(
      'name', a.supplied_name, 'source_url', a.source_url, 'reviewed_at', '2026-09-26'
    )),
  true
)
FROM _east_coast_aliases AS a
WHERE b.id = a.target_id AND b.slug = a.target_slug AND b.deleted_at IS NULL
  AND NOT COALESCE(b.preference_model->'catalog_aliases', '[]'::jsonb)
    @> jsonb_build_array(jsonb_build_object('name', a.supplied_name));

DO $$
DECLARE
  imported integer;
  gated integer;
  forecast_ready integer;
  tide_mismatches integer;
  hero_coverage integer;
BEGIN
  SELECT count(*) INTO imported
  FROM public.beaches b JOIN _east_coast_beaches i USING (id)
  WHERE b.deleted_at IS NULL;
  IF imported <> 61 THEN RAISE EXCEPTION 'Expected 61 active imported beaches, found %', imported; END IF;

  IF EXISTS (
    SELECT 1 FROM public.beaches b JOIN _east_coast_beaches i USING (id)
    WHERE (b.aspect_deg, b.wind_offshore_deg, b.swell_window_min_deg,
           b.swell_window_max_deg, b.swell_window_center_deg, b.swell_window_halfwidth_deg,
           b.skill_level, b.timezone, b.recommendation_eligible, b.seo_indexable, b.is_private,
           b.swell_window_min_deg_v2, b.swell_window_max_deg_v2,
           b.swell_window_center_deg_v2, b.swell_window_halfwidth_deg_v2)
      IS DISTINCT FROM
          (i.aspect, i.offshore, i.swell_min, i.swell_max, i.swell_center, i.swell_halfwidth,
           i.skill_level, i.timezone, i.recommendation_eligible, i.seo_indexable, i.is_private,
           i.swell_min, i.swell_max, i.swell_center, i.swell_halfwidth)
      OR b.preference_model->'precision_review' IS DISTINCT FROM i.precision_review
      OR b.preference_model->'tide' IS DISTINCT FROM COALESCE(to_jsonb(i.tide_stage), 'null'::jsonb)
      OR b.preference_model->'tide_calibration'->>'note' IS DISTINCT FROM i.tide_note
      OR b.preference_model->'forecast_anchors'->'nws_used_coordinate'
        IS DISTINCT FROM jsonb_build_array(i.nws_used_lat, i.nws_used_lon)
      OR b.preference_model->'forecast_anchors'->'nws_original_coordinate'
        IS DISTINCT FROM jsonb_build_array(i.lat, i.lon)
      OR b.preference_model->'forecast_anchors'->>'nws_point_reviewed' IS DISTINCT FROM 'true'
      OR b.preferred_tide_ft_min IS NOT NULL OR b.preferred_tide_ft_max IS NOT NULL
  ) THEN RAISE EXCEPTION 'Stored forecast/editorial fields differ from reviewed seed'; END IF;

  SELECT count(*) INTO gated
  FROM public.beaches b JOIN _east_coast_beaches i USING (id)
  WHERE NOT b.recommendation_eligible OR NOT b.seo_indexable OR b.is_private;
  IF gated <> 1 THEN RAISE EXCEPTION 'Expected only Southern Duck to remain gated, found % rows', gated; END IF;

  SELECT count(*) INTO forecast_ready
  FROM public.beach_sources s
  JOIN _east_coast_beaches i ON i.id = s.beach_id
  WHERE s.forecast_source_id = 'open_meteo';
  IF forecast_ready <> 61 THEN RAISE EXCEPTION 'Expected 61 Open-Meteo source rows, found %', forecast_ready; END IF;

  IF EXISTS (
    SELECT 1 FROM _east_coast_beaches i
    LEFT JOIN public.beach_sources s ON s.beach_id = i.id
    LEFT JOIN _east_coast_cameras c ON c.beach_id = i.id
    WHERE s.camera_url IS DISTINCT FROM c.camera_url
       OR (c.beach_id IS NOT NULL AND s.thumbnail_url IS DISTINCT FROM c.thumbnail_url)
  ) OR (
    SELECT count(*) FROM public.beach_sources s JOIN _east_coast_beaches i ON i.id = s.beach_id
    WHERE s.camera_url IS NOT NULL
  ) <> 7 THEN RAISE EXCEPTION 'Expected exactly seven reviewed Surfline camera assignments'; END IF;

  IF (
    SELECT count(*) FROM public.beaches b JOIN _east_coast_beaches i USING (id)
    WHERE b.terrain_enabled AND b.terrain_status = 'ok'
      AND array_length(b.swell_access_factors, 1) = 72
      AND array_length(b.wind_exposure_factors, 1) = 72
      AND b.terrain_params_hash = 'ca84656a8a0e721a7c47813f541c147bcbe81157b1d6ed054c715b21119cc659'
  ) <> 61 THEN RAISE EXCEPTION 'Expected 61 complete reviewed terrain fingerprints'; END IF;

  IF (
    SELECT count(*) FROM public.beaches b JOIN _east_coast_aliases a ON b.id = a.target_id AND b.slug = a.target_slug
    WHERE b.deleted_at IS NULL AND b.preference_model->'catalog_aliases'
      @> jsonb_build_array(jsonb_build_object('name', a.supplied_name))
  ) <> 9 THEN RAISE EXCEPTION 'Expected all nine reviewed catalog aliases'; END IF;

  SELECT count(*) INTO tide_mismatches
  FROM public.beaches b
  JOIN _east_coast_beaches i USING (id)
  WHERE b.preferred_tide_direction IS DISTINCT FROM i.preferred_tide_direction
     OR b.tide_direction_sensitivity IS DISTINCT FROM 'low';
  IF tide_mismatches <> 0 THEN
    RAISE EXCEPTION 'Tide preferences differ from reviewed seed: % rows', tide_mismatches;
  END IF;

  SELECT count(DISTINCT p.beach_id) INTO hero_coverage
  FROM public.beach_photos p
  JOIN _east_coast_beaches i ON i.id = p.beach_id
  WHERE p.approved AND p.deleted_at IS NULL;
  IF hero_coverage <> 61 THEN
    RAISE EXCEPTION 'Expected approved hero coverage for all 61 imported beaches, found %', hero_coverage;
  END IF;

  IF (
    SELECT count(*)
    FROM public.beach_photos p
    JOIN _east_coast_beaches i ON i.id = p.beach_id
    WHERE p.source = 'wikimedia' AND p.approved AND p.deleted_at IS NULL
  ) < 8 THEN
    RAISE EXCEPTION 'Expected at least eight approved reviewed hero images';
  END IF;
END $$;

COMMIT;
